#!/usr/bin/env node
// SPDX-License-Identifier: FSL-1.1-MIT
/**
 * Build or verify the committed GitHub Action distribution.
 *
 * GitHub's JavaScript-action contract requires dependencies to travel with the action checkout.
 * We commit one deterministic bundle rather than node_modules or a mutable runtime install. The
 * accompanying notice is derived from esbuild's exact input graph and contains the complete
 * licence text for every bundled third-party package.
 */

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ENTRY = path.join(ROOT, 'src', 'action-entry.mjs');
const OUTPUT = path.join(ROOT, 'dist', 'holt-action.mjs');
const NOTICES = path.join(ROOT, 'dist', 'THIRD-PARTY-NOTICES.txt');
const CHECK = process.argv.includes('--check');

const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');

async function packageForInput(input) {
  let directory = path.dirname(path.resolve(ROOT, input));
  while (directory.includes(`${path.sep}node_modules${path.sep}`)) {
    try {
      const manifestPath = path.join(directory, 'package.json');
      const manifest = JSON.parse(await fs.readFile(manifestPath, 'utf8'));
      if (typeof manifest.name === 'string' && typeof manifest.version === 'string') {
        return { directory, manifest };
      }
    } catch { /* keep walking to the package root */ }
    const parent = path.dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  return null;
}

async function thirdPartyNotices(inputs) {
  const packages = new Map();
  for (const input of inputs) {
    if (!input.includes('node_modules/')) continue;
    const found = await packageForInput(input);
    if (found) packages.set(`${found.manifest.name}@${found.manifest.version}`, found);
  }

  const sections = [];
  for (const [identity, { directory, manifest }] of [...packages].sort(([a], [b]) => a.localeCompare(b))) {
    const names = (await fs.readdir(directory))
      .filter((name) => /^(licen[sc]e|copying|notice)(\.|$)/iu.test(name))
      .sort();
    if (names.length === 0) {
      throw new Error(`bundled dependency ${identity} has no distributable licence/notice file`);
    }
    const texts = [];
    for (const name of names) texts.push(`${name}\n\n${(await fs.readFile(path.join(directory, name), 'utf8')).trim()}`);
    sections.push(`${'='.repeat(80)}\n${identity} — declared licence: ${manifest.license ?? 'see text'}\n${'='.repeat(80)}\n\n${texts.join('\n\n')}`);
  }
  return `Holt GitHub Action — third-party notices\n\n`
    + `Generated from the exact dependency modules embedded in dist/holt-action.mjs.\n\n`
    + `${sections.join('\n\n')}\n`;
}

async function sourceFingerprint(inputs) {
  const digest = createHash('sha256');
  const paths = [...new Set([...inputs, 'package.json'])].sort();
  for (const relative of paths) {
    digest.update(`${relative}\0`);
    digest.update(await fs.readFile(path.resolve(ROOT, relative)));
    digest.update('\0');
  }
  digest.update('esbuild:0.28.1;platform=node;format=esm;target=node24;mainFields=module,main');
  return digest.digest('hex');
}

async function buildOutputs() {
  const temporary = await fs.mkdtemp(path.join(os.tmpdir(), 'holt-action-build-'));
  const temporaryOutput = path.join(temporary, 'holt-action.mjs');
  try {
    const result = await build({
      entryPoints: [ENTRY],
      outfile: temporaryOutput,
      bundle: true,
      platform: 'node',
      format: 'esm',
      target: 'node24',
      mainFields: ['module', 'main'],
      charset: 'utf8',
      legalComments: 'eof',
      logLevel: 'silent',
      metafile: true,
    });
    const inputs = Object.keys(result.metafile.inputs).sort();
    const raw = await fs.readFile(temporaryOutput, 'utf8');
    const withoutShebang = raw.replace(/^#![^\n]*\n/u, '');
    const fingerprint = await sourceFingerprint(inputs);
    const bundle = `#!/usr/bin/env node\n`
      + `// GENERATED by scripts/build-action-bundle.mjs — do not hand-edit.\n`
      + `// Exact source/dependency fingerprint: ${fingerprint}\n`
      + withoutShebang;
    const notices = await thirdPartyNotices(inputs);
    return { bundle, notices, fingerprint, inputs: inputs.length };
  } finally {
    await fs.rm(temporary, { recursive: true, force: true });
  }
}

async function assertCurrent(file, expected, label) {
  let current;
  try { current = await fs.readFile(file, 'utf8'); } catch { current = null; }
  if (current !== expected) {
    throw new Error(`${label} is ${current === null ? 'missing' : 'stale'}; run: npm run action:build`);
  }
}

const result = await buildOutputs();
if (CHECK) {
  await assertCurrent(OUTPUT, result.bundle, 'dist/holt-action.mjs');
  await assertCurrent(NOTICES, result.notices, 'dist/THIRD-PARTY-NOTICES.txt');
  process.stdout.write(`GitHub Action bundle is current: ${result.inputs} inputs, ${Buffer.byteLength(result.bundle)} bytes, ${result.fingerprint}\n`);
} else {
  await fs.mkdir(path.dirname(OUTPUT), { recursive: true });
  await fs.writeFile(OUTPUT, result.bundle, { mode: 0o755 });
  await fs.chmod(OUTPUT, 0o755);
  await fs.writeFile(NOTICES, result.notices, { mode: 0o644 });
  process.stdout.write(`wrote dist/holt-action.mjs and dist/THIRD-PARTY-NOTICES.txt (${result.inputs} inputs, ${result.fingerprint})\n`);
}
